    scoutTitle:'\u06A9\u0627\u0648\u0634\u06AF\u0631 \u0634\u0628\u06A9\u0647\u0654 \u0647\u062F\u0641',scoutSubtitle:'\u0627\u0628\u062A\u062F\u0627 \u06F4\u06F0 \u06CC\u0627 \u06F8\u06F0 \u0646\u0627\u0645\u0632\u062F \u0631\u0633\u0645\u06CC Cloudflare \u0628\u0627 \u062F\u0648 \u062F\u0648\u0631 TLS/SNI \u0648 WebSocket \u0631\u0648\u06CC \u0634\u0628\u06A9\u0647\u0654 \u0639\u0627\u0645\u0644 \u063A\u0631\u0628\u0627\u0644 \u0645\u06CC\u200C\u0634\u0648\u0646\u062F\u061B \u0633\u067E\u0633 \u0641\u0642\u0637 \u062A\u0627 \u06F1\u06F0 \u0645\u0648\u0631\u062F \u0628\u0631\u062A\u0631 \u062F\u0631 \u0645\u0623\u0645\u0648\u0631\u06CC\u062A\u06CC \u062C\u062F\u0627\u06AF\u0627\u0646\u0647 \u0628\u0627 VLESS \u0648 Trojan \u0648\u0627\u0642\u0639\u0627\u064B \u0622\u0632\u0645\u0627\u06CC\u0634 \u0645\u06CC\u200C\u0634\u0648\u0646\u062F.',
