    scoutRun:'\u0634\u0631\u0648\u0639 \u06A9\u0627\u0648\u0634 \u0648 \u0622\u0632\u0645\u0648\u0646 \u0648\u0627\u0642\u0639\u06CC',scoutWarn:'\u063A\u0631\u0628\u0627\u0644 \u0627\u0648\u0644\u06CC\u0647 \u0627\u0632 \u0633\u0647\u0645\u06CC\u0647\u0654 \u06A9\u0627\u0631\u0628\u0631 \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u0646\u0645\u06CC\u200C\u06A9\u0646\u062F\u061B \u0645\u0631\u062D\u0644\u0647\u0654 \u062F\u0648\u0645 \u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u062F \u0627\u0639\u062A\u0628\u0627\u0631 \u0648 \u062D\u062C\u0645 \u06A9\u0627\u0631\u0628\u0631 \u0631\u0627 \u0645\u0635\u0631\u0641 \u06A9\u0646\u062F. IP\u0647\u0627\u06CC \u063A\u0631\u0628\u0627\u0644\u200C\u0634\u062F\u0647 \u0628\u0647\u200C\u062A\u0646\u0647\u0627\u06CC\u06CC \u0633\u0627\u0644\u0645 \u06CC\u0627 \u0622\u0645\u0627\u062F\u0647\u0654 \u0627\u0634\u062A\u0631\u0627\u06A9 \u0646\u06CC\u0633\u062A\u0646\u062F.',
