    $('#topTitle').textContent = title;
    $('#crumbCurrent').textContent = state.page === 'home' ? tr('dashboard') : title;
    for (const node of document.querySelectorAll('.nav-item')) node.classList.toggle('active', node.dataset.page === state.page);
